/* ============================================================
   AgendaBot :: Helpers comunes (sin dependencias externas)
   Zona horaria fija: America/Bogota (UTC-5, sin horario de verano)
   ============================================================ */
const TZ_OFFSET_MS = -5 * 60 * 60 * 1000;
function pad(n, l) { return String(n).padStart(l, '0'); }
function ahora() { return new Date(Date.now() + TZ_OFFSET_MS); }
function aFechaISO(d) { return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1, 2) + '-' + pad(d.getUTCDate(), 2); }
function aHoraHM(d) { return pad(d.getUTCHours(), 2) + ':' + pad(d.getUTCMinutes(), 2); }
function hoyISO() { return aFechaISO(ahora()); }
function horaActual() { return aHoraHM(ahora()); }
function timestampCO() { const d = ahora(); return aFechaISO(d) + ' ' + aHoraHM(d) + ':' + pad(d.getUTCSeconds(), 2); }
function sumarDias(f, n) {
  const p = String(f).split('-').map(Number);
  return aFechaISO(new Date(Date.UTC(p[0], p[1] - 1, p[2] + n)));
}
function esFechaValida(s) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(s || ''))) return false;
  const p = String(s).split('-').map(Number);
  if (p[1] < 1 || p[1] > 12) return false;
  const diasMes = new Date(Date.UTC(p[0], p[1], 0)).getUTCDate();
  return p[2] >= 1 && p[2] <= diasMes && p[0] >= 2000 && p[0] <= 2100;
}
function esHoraValida(s) { return /^([01]\d|2[0-3]):[0-5]\d$/.test(String(s || '')); }
function esPasado(f, h) {
  const hoy = hoyISO();
  if (f < hoy) return true;
  if (f === hoy && h && h <= horaActual()) return true;
  return false;
}
function vacio(s) { return String(s == null ? '' : s).trim().length === 0; }
function limpiar(s) { return String(s == null ? '' : s).trim().replace(/\s+/g, ' ').slice(0, 200); }
function filasReales(items, clave) {
  return items.map(function (i) { return i.json; })
              .filter(function (r) { return r && r[clave] != null && String(r[clave]).trim() !== ''; });
}
function siguienteId(filas, campo, prefijo) {
  let max = 0;
  for (const r of filas) {
    const m = String(r[campo] || '').match(/(\d+)\s*$/);
    if (m) { const n = parseInt(m[1], 10); if (n > max) max = n; }
  }
  return prefijo + '-' + pad(max + 1, 3);
}
function leerDatos(t) { try { const o = JSON.parse(t || '{}'); return (o && typeof o === 'object') ? o : {}; } catch (e) { return {}; } }
function esVerdadero(v) {
  const s = String(v == null ? '' : v).trim().toUpperCase();
  return s === 'TRUE' || s === 'VERDADERO' || s === 'SI' || s === 'SÍ' || s === '1' || s === 'X' || s === 'YES';
}
const PIE = '\n————————\n9 Volver   ·   /menu Menú principal   ·   /cancelar Cancelar';
function opcionInvalida(extra) {
  return '⚠️ No entendí esa opción.\n' + (extra || 'Escribe únicamente el número de una de las opciones mostradas.');
}
function salida(mensaje, pantalla, paso, datos, resultado, accion, fila) {
  return [{ json: {
    mensaje: String(mensaje).slice(0, 3900),
    pantalla_nueva: pantalla,
    paso_nuevo: String(paso),
    datos_parciales: JSON.stringify(datos || {}),
    resultado: resultado || 'OK',
    accion: accion || 'NINGUNA',
    fila: fila || {}
  }}];
}

/* =====================================================================
   MODULO LISTAS
   Pantallas: LISTAS | LISTAS_NUEVA (2 pasos) | LISTAS_ABRIR (1 paso)
              LISTAS_ITEMS (menu) | LISTAS_AGREGAR | LISTAS_COMPLETAR
              LISTAS_ELIMINAR
   Hojas: LISTAS(id_lista, nombre_lista, tipo, creado_por)
          ITEMS_LISTA(id_item, id_lista, item, estado)
   ===================================================================== */
const ctx = $('▶️ Entrada Listas').first().json;
const listas = filasReales($('📄 LISTAS - Leer').all(), 'id_lista');
const items = filasReales($input.all(), 'id_item');

const texto = String(ctx.texto || '').trim();
const pantalla = String(ctx.pantalla_actual || 'LISTAS').toUpperCase();
const paso = String(ctx.paso_actual || '0');
const usuario = String(ctx.telegram_user);
const d = leerDatos(ctx.datos_parciales);

const TIPOS = { '1': 'COMPRAS', '2': 'TAREAS', '3': 'IDEAS', '4': 'OTRO' };
const ICONO = { 'PENDIENTE': '⬜', 'COMPLETADO': '✅', 'ELIMINADO': '🗑️' };

const MENU =
  '📝 LISTAS\n' +
  'Aquí guardas listas de compras, ideas o pendientes.\n\n' +
  '1  Crear lista\n' +
  '2  Ver mis listas\n' +
  '3  Abrir una lista y gestionar sus ítems\n' +
  '9  Volver al menú principal\n\n' +
  '💡 Recomendado: 3 Abrir una lista\n' +
  'Tip: escribe únicamente el número.';

/* Entrada directa desde el menu principal: se muestra el menu del modulo
   sin consumir el numero que el usuario uso para entrar. */
if (ctx.entrada_modulo === true || String(ctx.entrada_modulo) === 'true')
  return salida(MENU, 'LISTAS', '0', {}, 'MENU_LISTAS');


function misListas() {
  return listas.filter(function (l) { return String(l.creado_por || '').trim() === usuario; })
               .sort(function (a, b) { return String(a.id_lista).localeCompare(String(b.id_lista)); });
}
function itemsDe(idLista, soloVivos) {
  return items.filter(function (i) {
    return String(i.id_lista || '').trim() === String(idLista) &&
           (!soloVivos || String(i.estado || '').toUpperCase() !== 'ELIMINADO');
  });
}
function listadoListas(ls) {
  return ls.map(function (l, i) {
    const n = itemsDe(l.id_lista, true);
    const p = n.filter(function (x) { return String(x.estado || '').toUpperCase() === 'PENDIENTE'; });
    return (i + 1) + ')  ' + l.nombre_lista + '   [' + l.tipo + ']' +
           '\n      ' + n.length + ' ítems · ' + p.length + ' pendientes · ' + l.id_lista;
  }).join('\n');
}
function listadoItems(is) {
  if (is.length === 0) return '   (esta lista todavía no tiene ítems)';
  return is.map(function (x, i) {
    const e = String(x.estado || '').toUpperCase();
    return '   ' + (i + 1) + ')  ' + (ICONO[e] || '•') + ' ' + x.item + '   · ' + x.id_item;
  }).join('\n');
}
function menuItems(lista) {
  const is = itemsDe(lista.id_lista, true);
  return '📂 LISTA: ' + lista.nombre_lista + '   [' + lista.tipo + ']\n\n' +
         listadoItems(is) + '\n\n' +
         '1  Agregar ítem\n' +
         '2  Completar ítem\n' +
         '3  Eliminar ítem\n' +
         '9  Volver a Listas\n\n' +
         '💡 Recomendado: 1 Agregar ítem';
}
function filaItem(x, cambios) {
  return {
    id_item: x.id_item,
    id_lista: x.id_lista,
    item: (cambios && cambios.item) || x.item,
    estado: (cambios && cambios.estado) || x.estado
  };
}

const L1 = '🆕 NUEVA LISTA — Paso 1 de 2: NOMBRE\n\n' +
           '¿Cómo se va a llamar la lista?\n\nEjemplo: Mercado del sábado\n\n' +
           '9 Volver   ·   /cancelar Cancelar';
const L2 = '🆕 NUEVA LISTA — Paso 2 de 2: TIPO\n\n' +
           '¿De qué tipo es?\n\n1  Compras\n2  Tareas\n3  Ideas\n4  Otro\n\n' +
           '💡 Recomendado: 1 Compras\n9 Volver   ·   /cancelar Cancelar';

/* ------------------------------------------------------------------ MENU */
if (pantalla === 'LISTAS') {
  if (texto === '1') return salida(L1, 'LISTAS_NUEVA', '1', {}, 'WIZARD_INICIADO');
  if (texto === '2') {
    const ls = misListas();
    if (ls.length === 0)
      return salida('📭 Todavía no tienes listas.\n\nCrea la primera con la opción 1.\n\n' + MENU,
                    'LISTAS', '0', {}, 'CONSULTA_VACIA');
    return salida('📚 TUS LISTAS (' + ls.length + ')\n\n' + listadoListas(ls) + '\n\n' + MENU,
                  'LISTAS', '0', {}, 'CONSULTA_OK');
  }
  if (texto === '3') {
    const ls = misListas();
    if (ls.length === 0)
      return salida('📭 No tienes listas para abrir. Crea una con la opción 1.\n\n' + MENU,
                    'LISTAS', '0', {}, 'SIN_LISTAS');
    return salida('📂 ¿Cuál lista quieres abrir?\n\n' + listadoListas(ls) + '\n\n' +
                  'Escribe el número de la lista (1 a ' + ls.length + ').\n\n' +
                  '💡 Recomendado: 1\n9 Volver   ·   /cancelar Cancelar',
                  'LISTAS_ABRIR', '1', { opciones: ls.map(function (l) { return l.id_lista; }) },
                  'SELECCION_PEDIDA');
  }
  if (texto === '9') return salida('👌 Volvamos al menú principal.\n\nEscribe /menu para verlo.',
                                   'MENU', '0', {}, 'VOLVER');
  return salida(opcionInvalida('En Listas espero 1, 2, 3 o 9.') + '\n\n' + MENU,
                'LISTAS', '0', {}, 'OPCION_INVALIDA');
}

/* ------------------------------------------------------------ NUEVA LISTA */
if (pantalla === 'LISTAS_NUEVA') {
  if (paso === '1') {
    if (texto === '9') return salida(MENU, 'LISTAS', '0', {}, 'VOLVER');
    const n = limpiar(texto);
    if (vacio(n)) return salida('⚠️ El nombre no puede quedar vacío.\n\n' + L1,
                                'LISTAS_NUEVA', '1', d, 'VACIO');
    if (n.length < 3) return salida('⚠️ Usa al menos 3 caracteres.\n\n' + L1,
                                    'LISTAS_NUEVA', '1', d, 'NOMBRE_CORTO');
    const dup = misListas().some(function (l) {
      return String(l.nombre_lista || '').trim().toLowerCase() === n.toLowerCase();
    });
    if (dup) return salida('⚠️ Ya tienes una lista con ese nombre.\n\n' + L1,
                           'LISTAS_NUEVA', '1', d, 'NOMBRE_DUPLICADO');
    d.nombre = n;
    return salida('✅ Nombre registrado: ' + d.nombre + '\n\n' + L2,
                  'LISTAS_NUEVA', '2', d, 'PASO_1_OK');
  }
  if (paso === '2') {
    if (texto === '9') return salida(L1, 'LISTAS_NUEVA', '1', d, 'VOLVER_PASO');
    const t = TIPOS[texto];
    if (!t) return salida(opcionInvalida('Para el tipo espero 1, 2, 3 o 4.') + '\n\n' + L2,
                          'LISTAS_NUEVA', '2', d, 'TIPO_INVALIDO');
    const id = siguienteId(listas, 'id_lista', 'LISTA');
    const f = { id_lista: id, nombre_lista: d.nombre, tipo: t, creado_por: usuario };
    return salida('🎉 Lista creada.\n\n🆔 ' + id + '\n📝 ' + f.nombre_lista + '\n🏷️ ' + t +
                  '\n\nÁbrela con la opción 3 para agregarle ítems.\n\n' + MENU,
                  'LISTAS', '0', {}, 'LISTA_CREADA:' + id, 'CREAR_LISTA', f);
  }
  return salida(L1, 'LISTAS_NUEVA', '1', {}, 'PASO_DESCONOCIDO');
}

/* ------------------------------------------------------------ ABRIR LISTA */
if (pantalla === 'LISTAS_ABRIR') {
  if (texto === '9') return salida(MENU, 'LISTAS', '0', {}, 'VOLVER');
  const ids = Array.isArray(d.opciones) ? d.opciones : [];
  const n = parseInt(texto, 10);
  if (!/^\d+$/.test(texto) || isNaN(n) || n < 1 || n > ids.length)
    return salida(opcionInvalida('Escribe un número entre 1 y ' + ids.length + '.'),
                  'LISTAS_ABRIR', '1', d, 'SELECCION_INVALIDA');
  const l = listas.find(function (r) { return String(r.id_lista) === String(ids[n - 1]); });
  if (!l) return salida('⚠️ No encontré esa lista.\n\n' + MENU, 'LISTAS', '0', {}, 'NO_ENCONTRADA');
  return salida(menuItems(l), 'LISTAS_ITEMS', '0', { id_lista: l.id_lista }, 'LISTA_ABIERTA:' + l.id_lista);
}

/* ------------------------------------------------------- GESTION DE ITEMS */
if (pantalla.indexOf('LISTAS_') === 0) {
  const l = listas.find(function (r) { return String(r.id_lista) === String(d.id_lista); });
  if (!l) return salida('⚠️ Perdí la referencia de la lista. Volvamos al inicio.\n\n' + MENU,
                        'LISTAS', '0', {}, 'CONTEXTO_PERDIDO');

  if (pantalla === 'LISTAS_ITEMS') {
    if (texto === '9') return salida(MENU, 'LISTAS', '0', {}, 'VOLVER');
    if (texto === '1')
      return salida('➕ Escribe el ítem que quieres agregar a "' + l.nombre_lista + '".\n\n' +
                    'Ejemplo: Leche deslactosada\n\n9 Volver   ·   /cancelar Cancelar',
                    'LISTAS_AGREGAR', '1', d, 'ITEM_PEDIDO');
    if (texto === '2' || texto === '3') {
      const pend = itemsDe(l.id_lista, true).filter(function (x) {
        return texto === '3' ? true : String(x.estado || '').toUpperCase() === 'PENDIENTE';
      });
      if (pend.length === 0)
        return salida('📭 No hay ítems disponibles para esa acción.\n\n' + menuItems(l),
                      'LISTAS_ITEMS', '0', d, 'SIN_ITEMS');
      const verbo = texto === '2' ? 'completar' : 'eliminar';
      const destino = texto === '2' ? 'LISTAS_COMPLETAR' : 'LISTAS_ELIMINAR';
      const nd = Object.assign({}, d, { opciones: pend.map(function (x) { return x.id_item; }) });
      return salida('🔧 ¿Cuál ítem quieres ' + verbo + '?\n\n' + listadoItems(pend) + '\n\n' +
                    'Escribe el número (1 a ' + pend.length + ').\n\n9 Volver   ·   /cancelar Cancelar',
                    destino, '1', nd, 'SELECCION_PEDIDA');
    }
    return salida(opcionInvalida('Aquí espero 1, 2, 3 o 9.') + '\n\n' + menuItems(l),
                  'LISTAS_ITEMS', '0', d, 'OPCION_INVALIDA');
  }

  if (pantalla === 'LISTAS_AGREGAR') {
    if (texto === '9') return salida(menuItems(l), 'LISTAS_ITEMS', '0', d, 'VOLVER');
    const t = limpiar(texto);
    if (vacio(t)) return salida('⚠️ El ítem no puede quedar vacío.\n\nEscribe el ítem:',
                                'LISTAS_AGREGAR', '1', d, 'VACIO');
    const dup = itemsDe(l.id_lista, true).some(function (x) {
      return String(x.item || '').trim().toLowerCase() === t.toLowerCase();
    });
    if (dup) return salida('⚠️ Ese ítem ya está en la lista.\n\nEscribe otro ítem:',
                           'LISTAS_AGREGAR', '1', d, 'ITEM_DUPLICADO');
    const id = siguienteId(items, 'id_item', 'ITEM');
    const f = { id_item: id, id_lista: l.id_lista, item: t, estado: 'PENDIENTE' };
    return salida('✅ Ítem agregado: ' + t + '\n\n' +
                  '(La lista de abajo se actualizará en tu próxima consulta.)\n\n' + menuItems(l),
                  'LISTAS_ITEMS', '0', d, 'ITEM_CREADO:' + id, 'CREAR_ITEM', f);
  }

  if (pantalla === 'LISTAS_COMPLETAR' || pantalla === 'LISTAS_ELIMINAR') {
    if (texto === '9') return salida(menuItems(l), 'LISTAS_ITEMS', '0', d, 'VOLVER');
    const ids = Array.isArray(d.opciones) ? d.opciones : [];
    const n = parseInt(texto, 10);
    if (!/^\d+$/.test(texto) || isNaN(n) || n < 1 || n > ids.length)
      return salida(opcionInvalida('Escribe un número entre 1 y ' + ids.length + '.'),
                    pantalla, '1', d, 'SELECCION_INVALIDA');
    const x = items.find(function (r) { return String(r.id_item) === String(ids[n - 1]); });
    if (!x) return salida('⚠️ No encontré ese ítem.\n\n' + menuItems(l),
                          'LISTAS_ITEMS', '0', d, 'NO_ENCONTRADO');
    const nuevo = pantalla === 'LISTAS_COMPLETAR' ? 'COMPLETADO' : 'ELIMINADO';
    const verbo = nuevo === 'COMPLETADO' ? '✅ Ítem completado' : '🗑️ Ítem eliminado';
    return salida(verbo + ': ' + x.item + '\n\n' + menuItems(l),
                  'LISTAS_ITEMS', '0', d, 'ITEM_' + nuevo + ':' + x.id_item,
                  'ACTUALIZAR_ITEM', filaItem(x, { estado: nuevo }));
  }
}

return salida(MENU, 'LISTAS', '0', {}, 'PANTALLA_DESCONOCIDA');

const r = $('🧠 Lógica de Listas').first().json;
return [{ json: {
  mensaje: r.mensaje, pantalla_nueva: r.pantalla_nueva, paso_nuevo: r.paso_nuevo,
  datos_parciales: r.datos_parciales, resultado: r.resultado
}}];
